609→const isMain = process.argv[1]
610→  && resolve(process.argv[1]) === fileURLToPath(import.meta.url);
611→
612→if (isMain) {
613→  const file = resolve(process.argv[2] ?? "evaluation/gate0/artifacts/gate0-upstream-capture.jsonl");
614→  const logFile = process.argv[3] ?? process.env.GATE0_TOOL_CALL_LOG;
615→
616→  const events = parseCapture(await readFile(file, "utf8"));
617→  const rows = logFile ? parseCapture(await readFile(resolve(logFile), "utf8")) : null;
618→
619→  const verdict = buildVerdict(events, rows);
