130→ */
131→export function parseBashToolResult(text) {
132→  if (typeof text !== "string" || !text.startsWith("Command:")) return null;
133→
134→  let exitCode = null;
135→  let tailStart = text.length;
136→  for (const match of text.matchAll(/\nExit Code: (-?\d+)(?:\n|$)/g)) {
137→    exitCode = Number.parseInt(match[1], 10);
138→    tailStart = match.index;
139→  }
140→
141→  const stdoutAt = text.indexOf("\nStdout:");
142→  const stderrAt = text.lastIndexOf("\nStderr:", tailStart);
143→  const hasStderr = stderrAt >= 0 && stderrAt > stdoutAt;
144→
145→  const commandEnd = stdoutAt >= 0 ? stdoutAt : hasStderr ? stderrAt : tailStart;
146→  const stdoutEnd = hasStderr ? stderrAt : tailStart;
147→
148→  const clean = (value) => {
149→    const trimmed = value.trim();
150→    return trimmed === "(empty)" ? "" : trimmed;
151→  };
152→
153→  return {
154→    command: text.slice("Command:".length, commandEnd).trim(),
155→    stdout: stdoutAt >= 0 ? clean(text.slice(stdoutAt + "\nStdout:".length, stdoutEnd)) : "",
156→    stderr: hasStderr ? clean(text.slice(stderrAt + "\nStderr:".length, tailStart)) : "",
157→    exitCode: Number.isNaN(exitCode) ? null : exitCode,
158→  };
159→}
160→
161→/**
162→ * Decide whether a parsed Bash result represents a successful asset fetch.
163→ *
164→ * Judged only on the response side: process exit status, curl's own error line,
165→ * and the bridge's `code` field. The echoed command is never consulted.
166→ */
167→export function classifyFetch(result, raw = "") {
168→  if (!result) {
169→    // The command never ran: the harness refused the tool before the shell saw it.
170→    // Distinct from a timeout, and the failure mode behind the very first Gate 0
171→    // run, where every asset curl was denied in non-interactive mode.
172→    if (/^Error: Permission to use (\w+) has been denied/.test(raw)) {
173→      return { ok: false, reason: "tool blocked by the harness before it ran" };
174→    }
175→    return { ok: false, reason: "not a Bash command result" };
176→  }
177→
178→  const curlError = /curl: \((\d+)\)\s*([^\n]*)/.exec(result.stderr);
179→  if (curlError) {
180→    return { ok: false, reason: `curl (${curlError[1]}) ${curlError[2]}`.trim() };
181→  }
182→  if (result.exitCode !== null && result.exitCode !== 0) {
183→    return { ok: false, reason: `command exited ${result.exitCode}` };
184→  }
185→  if (result.stdout.length === 0) {
186→    return { ok: false, reason: "exit 0 but no response body" };
187→  }
188→
189→  const code = /"code"\s*:\s*(-?\d+)/.exec(result.stdout);
190→  if (code && code[1] !== "0") {
191→    return { ok: false, reason: `bridge replied code=${code[1]}` };
192→  }
193→  return { ok: true, reason: code ? "exit 0, body code=0" : "exit 0, non-empty body" };
194→}
195→
196→/** Which channel an issued command targets, decided from its URL. */
197→export function channelForCommand(command) {
198→  if (typeof command !== "string") return null;
199→  for (const channel of ASSET_CHANNELS) {
200→    if (channel.urlPattern.test(command)) return channel.key;
201→  }
202→  return null;
203→}
204→
205→/**
206→ * Pair every tool result in a request body back to the call that issued it.
207→ *
208→ * Handles the OpenAI shape (`tool_calls[].id` ↔ `role:"tool"` + `tool_call_id`)
209→ * and the Anthropic shape (`tool_use.id` ↔ `tool_result.tool_use_id`). The pairing
210→ * key is what makes the judgment sound: an unrelated Grep result can no longer
211→ * satisfy a bridge channel, because it is not attached to a call that issued a
212→ * bridge URL.
213→ */
214→export function pairToolCalls(body) {
215→  const issued = new Map();
216→  const results = [];
217→
218→  for (const message of Array.isArray(body?.messages) ? body.messages : []) {
219→    for (const call of Array.isArray(message?.tool_calls) ? message.tool_calls : []) {
220→      if (call?.id) issued.set(call.id, textOf(call?.function?.arguments));
221→    }
222→    if (message?.role === "tool" && message?.tool_call_id) {
223→      results.push({ id: message.tool_call_id, result: textOf(message?.content) });
224→    }
225→
226→    const content = Array.isArray(message?.content) ? message.content : [];
227→    for (const block of content) {
228→      if (block?.type === "tool_use" && block?.id) issued.set(block.id, textOf(block?.input));
229→      else if (block?.type === "tool_result" && block?.tool_use_id) {
230→        results.push({ id: block.tool_use_id, result: textOf(block?.content) });
231→      }
232→    }
233→  }
234→
235→  return results.map((entry) => ({ ...entry, command: issued.get(entry.id) ?? null }));
236→}
237→
238→/** Which asset tool blocks are present in a system prompt. */
239→export function detectAssetBlocks(systemText) {
240→  return ASSET_BLOCKS.filter((name) => systemText.includes(`<${name}>`));
241→}
242→
243→/**
244→ * P9 — asset-reflection must never reach the wire during measured runs: it is a
245→ * cacheStrategy=none system suffix, so emitting it shifts the KV-cache prefix and
246→ * pollutes token/cost/latency metrics (see the evaluation protocol).
247→ */
248→export function detectReflectionLeak(systemText) {
249→  return systemText.includes("<asset_reflection>");
250→}
251→
252→/**
253→ * Reduce `tool_call_logs` rows (ClickHouse `FORMAT JSONEachRow`) into per-source
254→ * bridge-call outcomes.
255→ *
256→ * A row counts as a successful fetch only when the proxy actually reached the
257→ * upstream: `reject_reason` empty (a non-empty one means the proxy early-returned
258→ * and `upstream_status` holds the rejection status it sent back to the client)
259→ * and `upstream_status` in the 2xx range.
260→ */
261→export function summarizeBridgeRows(rows) {
262→  const bySource = new Map();
263→  let modelIntents = 0;
264→
265→  for (const row of Array.isArray(rows) ? rows : []) {
266→    if (row?.kind === "model_intent") {
267→      modelIntents += 1;
268→      continue;
269→    }
270→    if (row?.kind !== "bridge_call") continue;
271→
272→    const source = String(row.bridge_source ?? "");
273→    const status = Number(row.upstream_status ?? 0);
274→    const rejected = String(row.reject_reason ?? "").length > 0;
275→
276→    const entry = bySource.get(source)
277→      ?? { calls: 0, ok: 0, rejected: 0, failed: 0, endpoints: new Set(), statuses: new Set() };
278→    entry.calls += 1;
279→    entry.statuses.add(status);
280→    if (rejected) entry.rejected += 1;
281→    else if (status >= 200 && status < 300) {
282→      entry.ok += 1;
283→      entry.endpoints.add(String(row.executed_endpoint ?? "") || "?");
284→    } else entry.failed += 1;
285→    bySource.set(source, entry);
286→  }
287→
288→  return { bySource, modelIntents };
289→}
290→
291→/**
292→ * Reduce capture events — and, when available, proxy-side `tool_call_logs` rows —
293→ * into a Gate 0 verdict.
294→ *
295→ * @param {object[]} events capture events from the probe
296→ * @param {object[]|null} toolCallRows `tool_call_logs` rows, or null when the
297→ *   proxy's ClickHouse sink was off for this run
298→ */
299→export function buildVerdict(events, toolCallRows = null) {
300→  const requests = events.filter((event) => event?.event === "http.request");
301→  const responses = events.filter((event) => event?.event === "http.response");
302→  const errors = events.filter((event) => event?.event === "http.error");
303→
304→  const channels = Object.fromEntries(
305→    ASSET_CHANNELS.map((channel) => [
306→      channel.key,
307→      { ...channel, issued: false, wireFetched: false, wireFailures: new Map() },
308→    ]),
309→  );
310→  const blocksSeen = new Set();
311→  const judged = new Set();
312→  let reflectionLeaks = 0;
313→  let completionTurns = 0;
314→  let nativeToolUse = 0;
315→  let nativeToolResult = 0;
316→  let truncatedBodies = 0;
317→
318→  for (const request of requests) {
319→    const body = request?.body?.json;
320→    if (request?.body?.truncated) truncatedBodies += 1;
321→    if (!body || typeof body !== "object") continue;
322→
323→    if (Array.isArray(body.messages)) completionTurns += 1;
324→
325→    const systemText = extractSystemText(body);
326→    for (const name of detectAssetBlocks(systemText)) blocksSeen.add(name);
327→    if (detectReflectionLeak(systemText)) reflectionLeaks += 1;
328→
329→    nativeToolUse += request?.summary?.toolUseCount ?? 0;
330→    nativeToolResult += request?.summary?.toolResultCount ?? 0;
331→
332→    // The conversation is resent in full on every turn, so the same tool_call_id
333→    // recurs across requests. Judge each one once.
334→    for (const pair of pairToolCalls(body)) {
335→      if (judged.has(pair.id)) continue;
336→      judged.add(pair.id);
337→
338→      const key = channelForCommand(pair.command);
339→      if (!key) continue;
340→      const channel = channels[key];
341→      channel.issued = true;
342→
343→      const outcome = classifyFetch(parseBashToolResult(pair.result), pair.result);
344→      if (outcome.ok) channel.wireFetched = true;
345→      // Every distinct failure is kept: the first one is rarely the informative
346→      // one. A harness denial early in a run would otherwise hide the 75 s
347→      // connection timeout that came after it.
348→      else channel.wireFailures.set(outcome.reason, (channel.wireFailures.get(outcome.reason) ?? 0) + 1);
349→    }
350→  }
351→
352→  const telemetry = toolCallRows ? summarizeBridgeRows(toolCallRows) : null;
353→
354→  for (const channel of Object.values(channels)) {
355→    const stats = telemetry && channel.bridgeSource ? telemetry.bySource.get(channel.bridgeSource) : undefined;
356→    channel.bridge = stats ?? null;
357→    channel.bridgeFetched = Boolean(stats && stats.ok > 0);
358→
359→    if (channel.bridge) {
360→      channel.evidence = "bridge";
361→      channel.pass = channel.bridgeFetched;
362→    } else {
363→      channel.evidence = "wire";
364→      channel.pass = channel.wireFetched;
365→    }
366→  }
367→
368→  const describe = (channel) => {
369→    if (channel.evidence === "bridge") {
370→      const { ok, calls, rejected, failed, endpoints } = channel.bridge;
371→      return ok > 0
372→        ? `tool_call_logs: ${ok}/${calls} bridge_call 2xx (${[...endpoints].sort().join(", ")})`
373→        : `tool_call_logs: ${calls} bridge_call, none 2xx (rejected=${rejected}, failed=${failed})`;
374→    }
375→    if (channel.wireFetched) return "capture: curl exit 0 with a non-error body (wire-level `fetched`)";
376→    if (channel.issued) {
377→      const reasons = [...channel.wireFailures]
378→        .sort((a, b) => b[1] - a[1])
379→        .map(([reason, count]) => (count > 1 ? `${reason} (×${count})` : reason))
380→        .join("; ");
381→      return `capture: curl issued but never succeeded — ${reasons}`;
382→    }
383→    return "channel never exercised in this capture";
384→  };
385→
386→  const matrix = [
387→    {
388→      row: "Normal CodeBuddy turn",
389→      pass: completionTurns > 0,
390→      detail: `${completionTurns} request(s) carrying a messages array`,
391→    },
392→    {
393→      row: "Native CodeBuddy tool",
394→      pass: nativeToolUse > 0 && nativeToolResult > 0,
395→      detail: `tool_use=${nativeToolUse}, tool_result=${nativeToolResult}`,
396→    },
397→    ...Object.values(channels).map((channel) => ({
398→      row: channel.label,
399→      pass: channel.pass,
400→      evidence: channel.evidence,
401→      detail: describe(channel),
402→    })),
403→  ];
404→
405→  // Wire and bridge must tell the same story. Either direction of disagreement is
406→  // an instrument fault, not a data point.
407→  const disagreements = Object.values(channels)
408→    .filter((channel) => channel.bridge)
409→    .flatMap((channel) => {
410→      if (channel.wireFetched && !channel.bridgeFetched) {
411→        return [`${channel.label}: capture claims fetched, no 2xx bridge_call row — the capture judge is wrong`];
412→      }
413→      if (!channel.wireFetched && channel.bridgeFetched) {
414→        return [`${channel.label}: ${channel.bridge.ok} 2xx bridge_call row(s) the capture never saw — the tap has a hole`];
415→      }
416→      return [];
417→    });
418→
419→  // A bridge-tier channel passed on capture evidence alone. That is exactly the
420→  // judgment that produced three false positives, so it cannot authorize a freeze.
421→  const unbackedChannels = Object.values(channels)
422→    .filter((channel) => channel.tier === "bridge" && channel.pass && channel.evidence !== "bridge")
423→    .map((channel) => channel.label);
424→
425→  const checks = [
426→    {
427→      id: "P9",
428→      pass: reflectionLeaks === 0,
429→      detail: reflectionLeaks === 0
430→        ? "no <asset_reflection> block on the wire"
431→        : `${reflectionLeaks} request(s) carried <asset_reflection> — cost metrics would be polluted`,
432→    },
433→    {
434→      id: "capture-integrity",
435→      pass: truncatedBodies === 0 && errors.length === 0,
436→      detail: `truncated bodies=${truncatedBodies}, transport errors=${errors.length}`,
437→    },
438→    {
439→      id: "asset-blocks-injected",
440→      pass: blocksSeen.size > 0,
441→      // Passing on one block out of four would hide the case this names: an
442→      // injector that degraded to nothing. `knowledge_tools` in particular is only
443→      // rendered for knowledge bound in meta and already `ready`, so a draft or
444→      // unbound resource leaves the model unable to discover the channel at all —
445→      // even while the channel itself is fully observable. Absent blocks are
446→      // reported rather than folded into the PASS.
447→      detail: blocksSeen.size > 0
448→        ? [...blocksSeen].sort().join(", ")
449→          + (blocksSeen.size < ASSET_BLOCKS.length
450→            ? ` (not injected: ${ASSET_BLOCKS.filter((name) => !blocksSeen.has(name)).sort().join(", ")})`
451→            : "")
452→        : "no asset tool block observed in any system prompt",
453→    },
454→    // These two are the point of the rewrite, so neither may report PASS when it
455→    // had nothing to check with. An unrun check that renders as PASS is the same
456→    // falsely-reassuring signal the regex judge used to emit.
457→    {
458→      id: "evidence-source",
459→      status: telemetry === null ? "n/a" : unbackedChannels.length === 0 ? "pass" : "fail",
460→      detail: telemetry === null
461→        ? "no tool_call_logs supplied — bridge channels cannot be established from capture text alone"
462→        : unbackedChannels.length === 0
463→          ? "every bridge channel decided by proxy-side tool_call_logs"
464→          : `decided by capture text alone: ${unbackedChannels.join("; ")}`,
465→    },
466→    {
467→      id: "wire-bridge-agreement",
468→      status: telemetry === null ? "n/a" : disagreements.length === 0 ? "pass" : "fail",
469→      detail: telemetry === null
470→        ? "not checked — needs tool_call_logs to compare against"
471→        : disagreements.length === 0
472→          ? "capture and tool_call_logs agree on every bridge channel"
473→          : disagreements.join(" | "),
474→    },
475→  ].map((check) => ({
476→    ...check,
477→    status: check.status ?? (check.pass ? "pass" : "fail"),
478→    pass: (check.status ?? (check.pass ? "pass" : "fail")) === "pass",
479→  }));
480→
481→  // Reported, never silently passed: any channel that fell back to `wire` was
482→  // decided by the method this file exists to distrust. A null `bridgeSource` means
483→  // no sink exists; a non-null one with no rows means the sink was off or the
484→  // channel was never called. Those two are indistinguishable from here, so both
485→  // are named rather than assumed benign — the failure this gate guards against is
486→  // a run that renders "not checked" as "fine".
487→  const gaps = Object.values(channels)
488→    .filter((channel) => channel.evidence === "wire")
489→    .map((channel) => ({
490→      id: `${channel.key}-observability`,
491→      detail: channel.bridgeSource
492→        ? `${channel.label} produced no \`${channel.bridgeSource}\` rows in tool_call_logs — `
493→          + "its sink was off or the channel was never called, so this row rests on capture text alone"
494→        : `${channel.label} has no system-side sink at all, so this row rests on capture text alone`,
495→    }));
496→
497→  const matrixComplete = matrix.every((entry) => entry.pass);
498→  // `n/a` blocks the freeze as firmly as `fail`: not knowing is not the same as
499→  // being fine, and this gate exists to stop the second kind of mistake.
500→  const checksPass = checks.every((entry) => entry.status === "pass");
501→
502→  return {
503→    totals: { requests: requests.length, responses: responses.length, errors: errors.length },
504→    telemetry: telemetry
505→      ? {
506→        modelIntents: telemetry.modelIntents,
507→        bridges: Object.fromEntries(
508→          [...telemetry.bySource].map(([source, stats]) => [
509→            source,
510→            { ...stats, endpoints: [...stats.endpoints].sort(), statuses: [...stats.statuses].sort() },
511→          ]),
512→        ),
513→      }
514→      : null,
515→    matrix,
516→    checks,
517→    gaps,
518→    matrixComplete,
519→    schemaFreezeAllowed: matrixComplete && checksPass,
520→  };
521→}
522→
523→/** Render a verdict as a Markdown report. */
524→export function renderReport(verdict) {
525→  const mark = (pass) => (pass ? "PASS" : "FAIL");
526→  const lines = [
527→    "# Gate 0 capture verdict",
528→    "",
529→    `requests=${verdict.totals.requests} responses=${verdict.totals.responses} errors=${verdict.totals.errors}`,
530→    "",
531→  ];
532→
533→  if (verdict.telemetry) {
534→    lines.push(
535→      "## Proxy-side telemetry (tool_call_logs)",
536→      "",
537→      "| bridge_source | calls | 2xx | rejected | other | endpoints |",
538→      "|---|---|---|---|---|---|",
539→      ...Object.entries(verdict.telemetry.bridges).map(([source, stats]) =>
540→        `| ${source || "(empty)"} | ${stats.calls} | ${stats.ok} | ${stats.rejected} | ${stats.failed} | ${stats.endpoints.join(", ")} |`),
541→      "",
542→      `model_intent rows: ${verdict.telemetry.modelIntents}`,
543→      "",
544→    );
545→  } else {
546→    lines.push(
547→      "No tool_call_logs supplied — bridge channels fall back to capture text, which is",
548→      "not sufficient to freeze the schema. Export rows with `export-tool-call-logs.sh`.",
549→      "",
550→    );
551→  }
552→
553→  lines.push(
554→    "## Capture matrix",
555→    "",
556→    "| Row | Result | Evidence | Detail |",
557→    "|---|---|---|---|",
558→    ...verdict.matrix.map((entry) =>
559→      `| ${entry.row} | ${mark(entry.pass)} | ${entry.evidence ?? "-"} | ${entry.detail} |`),
560→    "",
561→    "## Checks",
562→    "",
563→    "| Check | Result | Detail |",
564→    "|---|---|---|",
565→    ...verdict.checks.map((entry) =>
566→      `| ${entry.id} | ${entry.status === "n/a" ? "n/a" : mark(entry.pass)} | ${entry.detail} |`),
567→    "",
568→  );
569→
570→  if (verdict.gaps.length > 0) {
571→    lines.push(
572→      "## Known observability gaps",
573→      "",
574→      ...verdict.gaps.map((gap) => `- **${gap.id}** — ${gap.detail}`),
575→      "",
576→    );
577→  }
578→
579→  lines.push(
580→    // Scope note: this verifier decides observability only — whether each channel
581→    // can be seen at all, and by which tier. Freezing the evidence-event schema
582→    // additionally requires the producer/actor provenance field set
583→    // (see the evidence model spec), which no capture can
584→    // establish. Saying "schema may be frozen" here once overstated what was
585→    // checked; the gate now reports what it actually verified.
586→    verdict.schemaFreezeAllowed
587→      ? "Verdict: observability complete and checks clean. Schema freeze additionally "
588→        + "requires the provenance fields in 02-evidence-model.md section 2."
589→      : "Verdict: observability incomplete — not ready to freeze the evidence-event schema.",
590→  );
591→
592→  return lines.join("\n");
593→}
